#!/usr/bin/env python3
"""F_2[t], f primitive of degree m (so (F_2[t]/f)^* is cyclic, generated by t).  Two 'pieces' of Sawin's decomposition
of the EOS count, computed for every class a by FFT:
  (i)  Moebius-EOS  (the sgn x sgn piece):   M(a)  = sum_{g1 g2 = a (f), deg g_i = m, monic} mu(g1) mu(g2)
       character side: (2^m/phi) sum_chi chibar(a) h_m(theta_chi)^2 * 2^m ;  int_{U(m-1)} |h_m|^4 = m+1  (m >= 3)
       EOS-type requirement: |M(a)| = o(2^m)  (trivial bound 2^m, Parseval bound 2^m exactly).
  (ii) smooth toy (m = 2k):  D4(a) = #{(e1..e4) monic of degree k : e1 e2 e3 e4 = a (f)},  mean 2^{4k}/phi ~ 2^m.
In char 2, mu(g) = (-1)^{m} psi(Berlekamp invariant): an Artin-Schreier phase, cf. route G2.
Usage: ff2_pieces.py mmin mmax"""
import sys, math, numpy as np
sys.path.insert(0, "../../routeD")
from ff2_eos import irreducible_table, log_table, clmul_shift

def mobius_deg(m, irr):
    """mu on all polynomials of degree exactly m (index = bitmask - 2^m)"""
    mu = np.ones(1 << m, dtype=np.int8)
    base = 1 << m
    for d in range(1, m + 1):
        ps = np.nonzero(irr[(1 << d):(1 << (d + 1))])[0] + (1 << d)
        g = np.arange(1 << (m - d), 1 << (m - d + 1), dtype=np.int64)
        g2 = np.arange(1 << (m - 2 * d), 1 << (m - 2 * d + 1), dtype=np.int64) if 2 * d <= m else None
        for p in ps:
            p = int(p)
            mu[clmul_shift(g, p) - base] *= -1
            if g2 is not None:
                p2 = int(clmul_shift(np.array([p], dtype=np.int64), p)[0])
                mu[clmul_shift(g2, p2) - base] = 0
    return mu

def run(m, irr, rng):
    order = (1 << m) - 1
    cands = np.nonzero(irr[(1 << m):(1 << (m + 1))])[0] + (1 << m)
    rng.shuffle(cands)
    for f in cands:
        f = int(f); lg = log_table(f, m)
        if lg is not None: break
    mu = mobius_deg(m, irr)
    assert abs(int(mu.astype(np.int64).sum())) <= 2            # sum of mu over degree m is 0 for m >= 2
    x = np.arange(1 << m, 1 << (m + 1), dtype=np.int64); res = x ^ f      # residues of monic degree-m polys; f -> 0
    ok = res != 0
    v = np.zeros(order); v[lg[res[ok]]] = mu[ok]
    F = np.fft.fft(v); M = np.fft.ifft(F * F).real
    out = (f"m={m:2d} f={f:#x}  Moebius-EOS: max|M|/2^m={np.abs(M).max()/2**m:7.4f} var(M)/2^m={(M**2).mean()/2**m:6.3f} (pred {m+1}) "
           f"max|M|/sqrt(2 var log phi)={np.abs(M).max()/math.sqrt(2*(M**2).mean()*math.log(order)):5.3f} kurt={(M**4).mean()/(M**2).mean()**2:5.3f}")
    if m % 2 == 0:
        k = m // 2
        w = np.zeros(order); w[lg[np.arange(1 << k, 1 << (k + 1))]] = 1.0
        G = np.fft.fft(w); D = np.rint(np.fft.ifft(G ** 4).real)
        mean = 2 ** (4 * k) / order
        out += (f" | toy D4: min/mean={D.min()/mean:6.3f} max/mean={D.max()/mean:6.3f} var/mean={((D-mean)**2).mean()/mean:8.2f} "
                f"zeros={(D==0).sum()} energy sum d_kk^2/2^m={(np.abs(G)**4).sum()/order/2**m:6.3f} (k+1={k+1})")
    print(out, flush=True)

if __name__ == "__main__":
    a, b = int(sys.argv[1]), int(sys.argv[2])
    irr = irreducible_table(b); rng = np.random.default_rng(3)
    for m in range(a, b + 1):
        run(m, irr, rng)
